package com.bank.stack;

import java.math.BigDecimal;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class ArrayStackDemo {
    private static final Logger log = Logger.getLogger(ArrayStackDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        ArrayStack stack = new ArrayStack(2);     // small initial capacity to force a resize
        stack.push(new BigDecimal("1000.00"));
        stack.push(new BigDecimal("2000.00"));
        stack.push(new BigDecimal("3000.00"));    // triggers resize 2 → 4

        log.info(() -> "Size after 3 pushes: " + stack.size());
        log.info(() -> "Peek top: Rs." + stack.peek());

        log.info(() -> "Pop: Rs." + stack.pop());   // 3000
        log.info(() -> "Pop: Rs." + stack.pop());   // 2000
        log.info(() -> "Peek top now: Rs." + stack.peek()); // 1000
        log.info(() -> "Is empty? " + stack.isEmpty());
    }
}

class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
