package com.bank.stack;

import java.math.BigDecimal;
import java.util.Arrays;

class ArrayStack {
    private BigDecimal[] data;
    private int top;              // index of top element; -1 when empty

    ArrayStack(int initialCapacity) {
        if (initialCapacity < 1) initialCapacity = 1;
        this.data = new BigDecimal[initialCapacity];
        this.top = -1;            // empty
    }

    // O(1) amortised: resize (double) when full, then store.
    void push(BigDecimal amount) {
        if (top + 1 == data.length) {
            data = Arrays.copyOf(data, data.length * 2);  // grow by doubling
        }
        data[++top] = amount;     // move top up, then write
    }

    // O(1): read top, clear slot, move top down.
    BigDecimal pop() {
        if (isEmpty()) {
            throw new IllegalStateException("pop on empty stack");
        }
        BigDecimal value = data[top];
        data[top] = null;         // help GC; avoid loitering reference
        top--;
        return value;
    }

    // O(1): read top without removing.
    BigDecimal peek() {
        if (isEmpty()) {
            throw new IllegalStateException("peek on empty stack");
        }
        return data[top];
    }

    boolean isEmpty() {
        return top == -1;
    }

    int size() {
        return top + 1;
    }
}
